<script setup lang="ts">
import {ref,onMounted,onUnmounted,nextTick} from 'vue'
import {X,ShieldCheck,ArrowRight} from 'lucide-vue-next'
import {api,user,refreshAccount,site,type User} from '../api/account'
const emit=defineEmits<{close:[];success:[]}>()
const register=ref(!!new URLSearchParams(location.search).get('invite')),username=ref(''),password=ref(''),confirm=ref(''),invite=ref(new URLSearchParams(location.search).get('invite')??''),error=ref(''),busy=ref(false),dialog=ref<HTMLElement|null>(null)
let previous:HTMLElement|null=null
onMounted(async()=>{previous=document.activeElement as HTMLElement;await nextTick();dialog.value?.querySelector('input')?.focus()})
onUnmounted(()=>previous?.focus())
function trap(e:KeyboardEvent){if(e.key!=='Tab')return;const nodes=dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled)');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
async function submit(){if(busy.value)return;error.value='';if(register.value&&site.value?.invite_required&&!invite.value.trim()){error.value='注册需要邀请码，请填写有效邀请码';return};if(register.value&&password.value!==confirm.value){error.value='两次输入的密码不一致';return};busy.value=true;try{user.value=await api<User>(register.value?'/auth/register':'/auth/login','POST',{username:username.value,password:password.value,invite_code:register.value?invite.value.trim():''});await refreshAccount();emit('success')}catch(e){error.value=e instanceof Error?e.message:'连接失败'}finally{busy.value=false}}
</script>
<template><div class="modal-overlay" @click.self="!busy&&emit('close')" @keydown.esc="!busy&&emit('close')" @keydown="trap"><section ref="dialog" class="modal auth-dialog" role="dialog" aria-modal="true" aria-labelledby="auth-title"><button class="modal-close icon-button" aria-label="关闭登录" :disabled="busy" @click="emit('close')"><X/></button><div class="auth-brand"><ShieldCheck :size="30"/></div><p class="section-eyebrow">YOUR STARLIGHT ACCOUNT</p><h2 id="auth-title">{{register?'注册星彩账户':'欢迎回来'}}</h2><p>{{register?'创建账户，开启你的精彩旅程。':'登录后查看余额、订单与团队收益。'}}</p><form class="form-stack" @submit.prevent="submit"><label>用户名<input v-model="username" required pattern="[A-Za-z0-9_]{4,32}" minlength="4" maxlength="32" autocomplete="username" placeholder="4–32位字母、数字、下划线"/></label><label>密码<input v-model="password" type="password" required minlength="10" maxlength="128" :autocomplete="register?'new-password':'current-password'" placeholder="至少10位密码"/></label><template v-if="register"><label>确认密码<input v-model="confirm" type="password" required minlength="10" maxlength="128" autocomplete="new-password" placeholder="再次输入密码"/></label><label>邀请码 <small>{{site?.invite_required?'必填':'选填'}}，注册后不可更改</small><input v-model="invite" :required="!!site?.invite_required" maxlength="12" placeholder="输入邀请人的邀请码"/></label></template><div v-if="error" class="form-error" role="alert">{{error}}</div><button class="primary-button" :disabled="busy">{{busy?'正在提交…':register?'注册并登录':'登录'}}<ArrowRight :size="17"/></button></form><button v-if="site?.registration||register" class="auth-switch" :disabled="busy" @click="register=!register;error=''">{{register?'已有账户？返回登录':'还没有账户？立即注册'}}</button></section></div></template>
